+  { name:'Ocean',   wax:new THREE.Color(0x2299ff), liquid:new THREE.Color(0xff7ac8), bulb:new THREE.Color(0x7ac8ff) },
+];
+let presetIdx = 0;
+const state = { power:true, heatLevel:1, warmup:1, heat:1.0, waxAmt:1.0, room:0.35, slow:false, time:0 };
