+    this.seed=Math.random()*100; this.stretch=1; this.active=true; this.pool=false;
+    this.wanderA=Math.random()*Math.PI*2; this.wanderS=0.2+Math.random()*0.5;
+    this.reset(true);
+  }
+  reset(scatter){
+    const a=Math.random()*Math.PI*2, rad=Math.random()*0.18;
+    this.pos.set(Math.cos(a)*rad, GLASS_Y0+0.22+ (scatter? Math.random()*1.7 : Math.random()*0.25), Math.sin(a)*rad);
