+$('waxAmt').addEventListener('input',e=>{ state.waxAmt=parseFloat(e.target.value); $('waxOut').textContent=Math.round(state.waxAmt*100)+'%'; });
+$('room').addEventListener('input',e=>{ state.room=parseFloat(e.target.value); $('roomOut').textContent=Math.round(state.room*100)+'%'; });
+$('slow').addEventListener('change',e=>{ state.slow=e.target.checked; });
+$('orbit').addEventListener('change',e=>{ controls.autoRotate=e.target.checked; });
+applyPreset(0);
+
+/* ---------- flicker from wax occluding the bulb ---------- */
+function bulbOcclusion(){
+  let occ=0;
+  for(const b of blobs){ if(!b.active) continue;
+    const dx=b.pos.x, dz=b.pos.z, dy=b.pos.y-1.15;
+    const d=Math.sqrt(dx*dx+dz*dz+dy*dy*0.6);
+    occ += Math.exp(-d*d*3.5) * b.r*1.4;
+  }
+  return THREE.MathUtils.clamp(occ,0,0.55);
+}
+
+/* ---------- adaptive quality ---------- */
+let fpsAcc=0, fpsN=0, fpsTimer=0;
+function adaptQuality(dt){
+  fpsAcc+=dt; fpsN++; fpsTimer+=dt;
+  if(fpsTimer>2.5){
+    const avg=fpsN/Math.max(fpsAcc,1e-3);
+    if(avg<42 && waxUniforms.uSteps.value>34){ waxUniforms.uSteps.value-=8; renderer.setPixelRatio(Math.max(1.0, renderer.getPixelRatio()-0.15)); composer.setPixelRatio(renderer.getPixelRatio()); }
+    else if(avg>57 && waxUniforms.uSteps.value<52){ waxUniforms.uSteps.value+=4; }
+    fpsAcc=0; fpsN=0; fpsTimer=0;
+  }
+}
+
+/* ---------- main loop (fixed-timestep wax) ---------- */
+const clock=new THREE.Clock();
+let accumulator=0; const FIXED=1/60;
+function animate(){
+  requestAnimationFrame(animate);
+  const rawDt=Math.min(clock.getDelta(), 0.05);
+  const timeScale=state.slow?0.22:1.0;
+  const dt=rawDt*timeScale;
+  accumulator+=dt;
+  let guard=0;
+  while(accumulator>=FIXED && guard<4){ stepWax(FIXED); accumulator-=FIXED; guard++; }
+  if(guard>=4) accumulator=0;
+  syncWaxUniforms();
+  // bulb + room respond to power, heat and wax occlusion (flicker/shift)
+  const occ=bulbOcclusion();
+  const flick=1 - occ*0.55 + Math.sin(state.time*13.7)*0.012*state.heatLevel + Math.sin(state.time*7.3+1.7)*0.01*state.heatLevel;
+  const bulbI=(2.0+16*state.heatLevel)*flick;
+  bulbLight.intensity=bulbI; spill.intensity=(0.5+5.0*state.heatLevel)*flick;
+  bulbMat.emissiveIntensity=0.08+3.1*state.heatLevel*flick;
+  bloom.strength=0.25+0.62*state.heatLevel;
+  const rm=state.room;
+  roomLight.intensity=rm*1.1; rimLight.intensity=0.06+rm*0.5; ambient.intensity=0.12+rm*0.85;
+  scene.environmentIntensity=0.10+rm*0.55;
+  gradePass.uniforms.uTime.value=performance.now()*0.001;
+  controls.update();
+  adaptQuality(rawDt);
+  composer.render();
+}
+animate();
+
+addEventListener('resize',()=>{
+  camera.aspect=innerWidth/innerHeight; camera.updateProjectionMatrix();
+  renderer.setSize(innerWidth,innerHeight); composer.setSize(innerWidth,innerHeight);
+  gradePass.uniforms.uAspect.value=innerWidth/innerHeight;
+});

